using Microsoft.EntityFrameworkCore;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<ShopDb>();
var app = builder.Build();

await using (var scope = app.Services.CreateAsyncScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ShopDb>();
    if (app.Environment.IsDevelopment())
        await db.Database.MigrateAsync(); // local convenience only
    else if ((await db.Database.GetPendingMigrationsAsync()).Any())
        // The deploy job should have run first: fail before serving traffic
        throw new InvalidOperationException("Database schema is behind");
}
app.Run();
